def can_make_interesting_problemset(n, k, knowledge):
    # Check all possible subsets of problems
    for subset in range(1, 1 << n):
        valid = True
        for team in range(k):
            known_problems = 0
            for problem in range(n):
                if subset & (1 << problem) and knowledge[problem][team]:
                    known_problems += 1
            if known_problems > (subset.bit_count() // 2):
